// Hand-rolled, not generated by a build plugin -- see README "PWA / installability" for why.
// Caches only the app shell (same-origin GET requests) so the UI can still load with zero
// connectivity. Never touches the Supabase API or any other cross-origin request -- the app's
// own Dexie/mutation-queue layer already owns that offline path.
const CACHE_NAME = 'otokwikk-shell-v1' // bump this string to force-invalidate old caches on deploy

self.addEventListener('install', () => {
  self.skipWaiting()
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((k) => k !== CACHE_NAME).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('fetch', (event) => {
  const url = new URL(event.request.url)
  if (event.request.method !== 'GET' || url.origin !== self.location.origin) return

  event.respondWith(
    fetch(event.request)
      .then((response) => {
        const copy = response.clone()
        caches.open(CACHE_NAME).then((cache) => cache.put(event.request, copy))
        return response
      })
      .catch(() => caches.match(event.request).then((cached) => cached || caches.match('/'))),
  )
})
